// these, which is the right answer to `is this list all there is` and the wrong
// one to `is this pane gone`: only the source that reads panes can say that. A
// reader that must decide whether a session it remembers is really absent asks
// the source that would have seen it.
type ScanSource struct {
	Complete bool `json:"complete"`

	// The source's provenance, as the adapter names it: `ps`, `tmux`, `iterm`.
	Source string `json:"source"`
}

type ScheduleDeleted struct {
	Deleted string `json:"deleted"`
	OK      bool   `json:"ok"`
}

type ScheduleDetail struct {
	Schedule ScheduleRecord `json:"schedule"`
}

type ScheduleLastRun struct {
	// When the run's task was created, Unix seconds.
	At int64 `json:"at"`

	// The task's state: queued, spawning, briefed, success, failure, timeout,
	// cancelled or spawn_failed.
	State  string `json:"state"`
	TaskID string `json:"task_id"`
}

type ScheduleList struct {
	At        int64         `json:"at"`
	Schedules []ScheduleRow `json:"schedules"`
}

// GET /v1/orchestrator/schedules/:id: one schedule in full — the template and
// the retained runs the list leaves out. `webhook_binding_availability` is
// `active` (with `webhook_hook_id`), `unbound`, or `binding_store_unavailable`.
type ScheduleRecord struct {
	CatchUpHours               int64            `json:"catch_up_hours"`
	CloseTab                   string           `json:"close_tab"`
	Enabled                    bool             `json:"enabled"`
	File                       string           `json:"file"`
	FiredAt                    int64            `json:"fired_at,omitempty"`
	ID                         string           `json:"id"`
	LastMissedAt               int64            `json:"last_missed_at,omitempty"`
	LastRun                    *ScheduleLastRun `json:"last_run,omitempty"`
	NextFire                   int64            `json:"next_fire,omitempty"`
	NotifyOnFailure            bool             `json:"notify_on_failure"`
	Once                       bool             `json:"once,omitempty"`
	Runs                       []ScheduleRun    `json:"runs"`
	RunsMayBeTruncated         bool             `json:"runs_may_be_truncated,omitempty"`
	Task                       ScheduleTask     `json:"task"`
	Title                      string           `json:"title"`
	WebhookBindingAvailability string           `json:"webhook_binding_availability"`
	WebhookHookID              string           `json:"webhook_hook_id,omitempty"`
	When                       ScheduleWhen     `json:"when"`
}

// The body POST /v1/orchestrator/schedules and PATCH
// /v1/orchestrator/schedules/:id take — the form's fields, flattened.
// `place_id` is an id from GET /v1/places, never a path. Exactly one of `days`
// and `on`; `days` is not defaulted. schedule_id, created_at, when_changed_at,
// fired_at and project_dir are the machine's and are refused as unknown fields.
// Writes need an Idempotency-Key and either a device that may send or, for a
// schedule that runs once, this machine's orchestrator token.
type ScheduleRequest struct {
	Assistant    string   `json:"assistant"`
	At           string   `json:"at"`
	CatchUpHours int64    `json:"catch_up_hours,omitempty"`
	CloseTab     string   `json:"close_tab,omitempty"`
	Days         []string `json:"days,omitempty"`
	Enabled      bool     `json:"enabled,omitempty"`
	Instructions string   `json:"instructions"`

	// No key leaves the model alone; an empty string takes it off.
	Model           string `json:"model,omitempty"`
	NotifyOnFailure bool   `json:"notify_on_failure,omitempty"`
	On              string `json:"on,omitempty"`
	PlaceID         string `json:"place_id"`
	TimeoutMinutes  int64  `json:"timeout_minutes,omitempty"`
	Title           string `json:"title"`
}

// One row of the list, in one of two shapes. A valid schedule carries id, title
// and enabled, and whichever of the rest apply. A schedule this daemon cannot
// parse carries only file, state (`invalid`), error and error_kind (`schema`,
// `project_unavailable` or `unreadable_json`) — it is listed rather than
// hidden, because a row that vanishes is a row nobody can fix. No task-template
// field is listed but project_dir.
type ScheduleRow struct {
	Enabled   bool   `json:"enabled,omitempty"`
	Error     string `json:"error,omitempty"`
	ErrorKind string `json:"error_kind,omitempty"`
	File      string `json:"file,omitempty"`

	// A schedule that runs once, and has: when its session opened. Such a schedule
	// never fires again.
	FiredAt int64  `json:"fired_at,omitempty"`
	ID      string `json:"id,omitempty"`

	// The most recent occurrence that expired outside its catch-up window.
	LastMissedAt int64            `json:"last_missed_at,omitempty"`
	LastRun      *ScheduleLastRun `json:"last_run,omitempty"`

	// The next local fire, Unix seconds. Absent for a schedule that will not fire
	// again.
	NextFire int64 `json:"next_fire,omitempty"`

	// Present and true for a schedule that runs once (`when.on`).
	Once       bool   `json:"once,omitempty"`
	ProjectDir string `json:"project_dir,omitempty"`

	// `invalid` on a row that could not be parsed; absent otherwise.
	State string `json:"state,omitempty"`
	Title string `json:"title,omitempty"`
}

// One task a schedule made, newest first in the detail. `summary` is what the
// task wrote when it finished.
type ScheduleRun struct {
	Assistant  string `json:"assistant"`
	Created    int64  `json:"created"`
	FinishedAt int64  `json:"finished_at,omitempty"`
	ProjectDir string `json:"project_dir"`
	SessionID  string `json:"session_id,omitempty"`
	State      string `json:"state"`
	Summary    string `json:"summary,omitempty"`
	TaskID     string `json:"task_id"`
	TerminalID string `json:"terminal_id,omitempty"`
}

// A made or saved schedule. `dispatch_enabled` rides beside a made one only:
// writing a schedule is not dispatching, and with task dispatch switched off
// nothing runs it.
type ScheduleSaved struct {
	DispatchEnabled bool            `json:"dispatch_enabled,omitempty"`
	OK              bool            `json:"ok"`
	Schedule        ScheduleSummary `json:"schedule"`
}

type ScheduleSummary struct {
	Enabled  bool   `json:"enabled"`
	ID       string `json:"id"`
	NextFire int64  `json:"next_fire,omitempty"`
	Title    string `json:"title"`
}

// The task template, as the file carries it. The fields a request may never
// name — project_dir, claims, permission_mode and the rest — are set in the
// file and carried across every save.
type ScheduleTask struct {
	Assistant       string   `json:"assistant"`
	Claims          []string `json:"claims,omitempty"`
	Deliverables    []string `json:"deliverables,omitempty"`
	Instructions    string   `json:"instructions"`
	Isolation       string   `json:"isolation,omitempty"`
	IsolationBase   string   `json:"isolation_base,omitempty"`
	Kind            string   `json:"kind,omitempty"`
	Model           string   `json:"model,omitempty"`
	PermissionMode  string   `json:"permission_mode,omitempty"`
	Plan            string   `json:"plan,omitempty"`
	ProjectDir      string   `json:"project_dir"`
	ReasoningEffort string   `json:"reasoning_effort,omitempty"`
	Serialize       []string `json:"serialize,omitempty"`
	TimeoutMinutes  int64    `json:"timeout_minutes,omitempty"`
	Title           string   `json:"title,omitempty"`
}

// `when` in the file's own spelling: `at` (HH:MM, local time) and exactly one
// of `days` (`daily`, or weekday names sun…sat) or `on` (YYYY-MM-DD, a
// schedule that runs once).
type ScheduleWhen struct {
	At   string   `json:"at"`
	Days []string `json:"days,omitempty"`
	On   string   `json:"on,omitempty"`
}

// What the clock says about its own last pass. A pass that fired nothing and a
// scheduler that stopped are both silence from outside, so the clock reports
// itself the way a scan does.
type SchedulerPulse struct {
	// When the last pass ran. Absent means no pass has finished yet, which is the
	// ordinary state for the first tick after startup.
	At         int64 `json:"at,omitempty"`
	Considered int64 `json:"considered"`

	// How many came due on this pass. Separate from `fired` because a due schedule
	// whose dispatch was refused is not the same as nothing being due.
	Due   int64 `json:"due"`
	Fired int64 `json:"fired"`

	// Why a pass did nothing, when the reason was not that nothing was due.
	Note        string `json:"note,omitempty"`
	TickSeconds int64  `json:"tickSeconds"`
}

// One reading of a terminal. `backend` and `channel` come first because a
// screen with no backend named is the defect this exists to avoid, and `lines`
// is what came back rather than what was asked for: an alternate-screen program
// has no history to give and this must not imply otherwise.
type Screen struct {
	// On `on-demand` only, said out loud rather than left for the client to discover:
	// nothing will tell it the screen moved, so asking again is the only way to see a
	// change, and this is the fastest it may.
	AskAgainAfterMs int64 `json:"askAgainAfterMs,omitempty"`

	// Unix seconds of the capture this text came from.
	At       int64         `json:"at,omitempty"`
	Backend  Backend       `json:"backend"`
	Captures int64         `json:"captures"`
	Channel  ScreenChannel `json:"channel"`
	ID       string        `json:"id"`

	// How many rows actually came back. The trailing newline a capture ends with is a
	// terminator, not a row.
	Lines int64 `json:"lines,omitempty"`

	// Nothing has been captured for this session yet. The first read of a session
	// answers this and the screen arrives a few milliseconds later on the `screen`
	// event, because the answer comes out of a published snapshot and the capture
	// happens behind it.
	Pending  bool `json:"pending"`
	Readable bool `json:"readable"`

	// What a client compares to decide whether it already has this screen. FNV-1a over
	// the UTF-8 bytes, which is enough for "did these change" and is deliberately not
	// a promise about anything else. An unreadable screen is the constant
	// `unreadable`, so a pane that stays unreadable stops producing events after the
	// first one.
	Revision string `json:"revision"`
	Signals  int64  `json:"signals"`

	// The capture, escape sequences kept. Absent until the first one completes.
	Text string `json:"text,omitempty"`

	// Unix seconds. The lease this read renewed; a lease nobody renews expires and
	// takes the pipe with it.
	WatchingUntil int64 `json:"watchingUntil"`
}

type ScreenAnswer struct {
	Screen Screen `json:"screen"`
}

// How a watcher finds out that a screen changed, which is a fact about the
// backend and not about the watcher. `signalled` is tmux with a pipe on the
// pane, about four milliseconds behind it; `on-demand` is a sample taken when
// somebody asks, no faster than `askAgainAfterMs`. Drawing the two identically
// would be a lie the reader has no way to catch, so it is in every payload.
type ScreenChannel string

const (
	ScreenChannelSignalled ScreenChannel = "signalled"
	ScreenChannelOnDemand  ScreenChannel = "on-demand"
)

// ScreenChannelValues is every value the contract allows, in contract order.
var ScreenChannelValues = []ScreenChannel{ScreenChannelSignalled, ScreenChannelOnDemand}

// The `screen` frame on /v1/events: only that a screen moved, and to what
// revision. The screen itself is fetched through the authenticated GET, exactly
// as a transcript append is — a stream frame reaches every device on this
// connection, and a terminal somebody else is watching has no business on it.
type ScreenEvent struct {
	At       int64  `json:"at"`
	ID       string `json:"id"`
	Revision string `json:"revision"`
}

// The machine state this feature creates, published so that somebody can see
// it. `tmux list-panes -a -F '#{pane_id} #{pane_pipe}'` answers the same
// question in one command; this answers it and says which of those pipes this
// daemon can account for, which tmux cannot, because `#{pane_pipe}` is a
// boolean with no owner in it. A pane that is piped and not on this daemon's
// list is therefore `unattributed` rather than a leak, and nothing here takes
// somebody else's pipe off.
type ScreenInventory struct {
	Attached     []string      `json:"attached"`
	LeaseSeconds int64         `json:"leaseSeconds"`
	Piped        []string      `json:"piped"`
	Screens      []ScreenWatch `json:"screens"`
	Unattributed []string      `json:"unattributed"`
	WindowMs     int64         `json:"windowMs"`
}

// One row of what this daemon is watching.
type ScreenWatch struct {
	Backend   Backend       `json:"backend"`
	Captures  int64         `json:"captures"`
	Channel   ScreenChannel `json:"channel"`
	ExpiresIn int64         `json:"expiresIn"`
	ID        string        `json:"id"`
	Readable  bool          `json:"readable"`

	// Whether this daemon has a pipe on that pane right now.
	Signalled bool  `json:"signalled"`
	Signals   int64 `json:"signals"`
	Watching  bool  `json:"watching"`
}

// Text, pictures, or both; a send that is neither is refused. Each picture is a
// base64 `data:` URL, at most six, inside the 20 MB body limit. Pictures that
// cannot be decoded are left out, and a send none of whose pictures can be is
// refused.
type SendRequest struct {
	Images []string `json:"images,omitempty"`
	Text   string   `json:"text,omitempty"`
}

// When this session last moved, from this daemon rather than from whatever each
// browser happened to have watched: the moment the session's own conversation
// record last grew. That one file follows both halves of a turn — the
// assistant appends its output to it and the person's message is appended to it
// too — so it is the single answer to a question that otherwise splits into
// three that disagree. State changes are not it: a session working since
// midnight changes state twice a night, and ordering by that would sink it
// below one that blinked an hour ago. The list orders by this inside each
// state, so an assistant still producing output at four in the morning reads as
// moving now, and a session somebody replied to ten minutes ago and which has
// gone quiet reads as ten minutes old and sits above one that stopped at
// midnight. Absent on a row no reading has answered for.
type SessionActivity struct {
	// Unix seconds: when the record last grew. Present only when `known`.
	At int64 `json:"at,omitempty"`

	// This machine's own sentence about the answer, for a reader deciding whether to
	// wait, fix this machine or stop asking.
	Detail   string   `json:"detail,omitempty"`
	Evidence Evidence `json:"evidence,omitempty"`

	// Whether there is a time. False is a real answer and carries `unknown_reason`: a
	// client must draw it as unknown and order it ahead of every known time inside its
	// state, never as a very old time. Of the two ways to be wrong about a row nobody
	// could read, only `it has been quiet for a week` hides the row somebody has to
	// act on.
	Known         bool                  `json:"known"`
	UnknownReason ActivityUnknownReason `json:"unknown_reason,omitempty"`
}

// Who this session is parked on, and who is parked on it. Absent when neither.
// `state` is `waiting_on_session` whenever `waitingOn` is not empty, otherwise
// `has_waiters`.
type SessionCoordination struct {
	State      string                `json:"state"`
	WaitedOnBy []CoordinationWaitRow `json:"waitedOnBy"`
	WaitingOn  []CoordinationWaitRow `json:"waitingOn"`
}

// Present on exactly the row whose live process is the one
// ~/.config/clawdline/coordinator.json registers — terminal, assistant, tty,
// pid, start time and conversation all equal. `status` is always `online` here,
// because the field is only attached to a matching live row.
type SessionCoordinator struct {
	Commands []SessionCoordinatorCommand `json:"commands"`
	Label    string                      `json:"label"`
	Status   string                      `json:"status"`
}

// One command in the Clawdfather panel. The list is the Swift app's fixed table
// (Coordinator.swift `commands`), in its order. `reason` and `why` are present
// only when `enabled` is false.
type SessionCoordinatorCommand struct {
	Enabled          bool   `json:"enabled"`
	Reason           string `json:"reason,omitempty"`
	TokenEffort      string `json:"token_effort"`
	TokenEffortBasis string `json:"token_effort_basis"`
	Type             string `json:"type"`
	Why              string `json:"why,omitempty"`
}

// The facts behind the status line under an open session. This daemon serves
// the transcript-derived part the Swift app calls the summary, the context
// reading and the plan windows; the working tree, links, permission and fast
// mode are not read here and their keys are absent.
type SessionInfo struct {
	Context *SessionInfoContext `json:"context,omitempty"`
	Limits  *SessionLimits      `json:"limits,omitempty"`
	Models  []SessionModel      `json:"models"`
	Session SessionInfoSession  `json:"session"`
	Usage   *SessionInfoUsage   `json:"usage,omitempty"`
}

// How full this conversation's context window is. The used side is counted —
// Claude's newest parent assistant turn, or Codex's own last turn — and
// survives a transcript too large to total, because the newest turn is at the
// end of the file. Absent when nothing said how much fits: a Claude session on
// a model with no window row and no status-line cache draws no reading at all,
// because unknown is not 0%.
type SessionInfoContext struct {
	// 0…100, clamped: a conversation past its window is full, not 104% full.
	UsedPercent float64 `json:"usedPercent"`

	// The counted used side. Absent when the only reading available was a percentage
	// somebody else worked out; also absent at exactly zero, which `usedPercent` still
	// states.
	UsedTokens int64 `json:"usedTokens,omitempty"`

	// How much fits — **only when the assistant itself said so** (Claude Code's
	// `context_window_size`, Codex's `model_context_window`). A window this daemon
	// guessed from the model id does not go on the wire, while `usedPercent` still
	// does: a percentage a client draws as one number is read as an approximation, and
	// `162,277 / 1,000,000 tokens` in a tooltip is read as a measurement — only one
	// of those two survives being wrong.
	WindowTokens int64 `json:"windowTokens,omitempty"`
}

// GET /v1/sessions/{id}/info. Kept off the session stream because answering
// reads the session's record; the console holds an answer for a minute.
type SessionInfoReply struct {
	Info SessionInfo `json:"info"`
}

type SessionInfoSession struct {
	Assistant Assistant `json:"assistant,omitempty"`
	CWD       string    `json:"cwd,omitempty"`
	ID        string    `json:"id"`

	// The model the session is on, as its record last named it: the newest assistant
	// turn's model, or a `/model` switch made after it. Absent when the record says
	// nothing.
	Model     string `json:"model,omitempty"`
	SessionID string `json:"sessionId,omitempty"`

	// The same label the session list shows.
	Title string `json:"title,omitempty"`
}

// What the conversation has spent. For Claude it is the sum of every assistant
// turn in the transcript and is absent when the transcript is larger than 8
// MiB, because a partial sum is not a total. For Codex it is Codex's own
// running total.
type SessionInfoUsage struct {
	CacheRead  int64 `json:"cacheRead"`
	CacheWrite int64 `json:"cacheWrite"`

	// US dollars. Claude Code's own session total from its status-line cache when it
	// wrote one, otherwise these tokens at list price. Absent when neither is known,
	// which is always the case for Codex; also absent at exactly zero.
	CostUsd float64 `json:"costUsd,omitempty"`
	Input   int64   `json:"input"`

	// The model the last counted turn named, as written.
	Model  string `json:"model,omitempty"`
	Output int64  `json:"output"`
	Total  int64  `json:"total"`
}

// One plan window, as the provider last described it.
type SessionLimitWindow struct {
	// The window is spent: the provider refused a request on it, or reported 100% or
	// more.
	Hit bool `json:"hit"`

	// `5h`, `7d`, or the window's length for any other (`1d`, `90m`).
	Name string `json:"name"`

	// Unix seconds. Absent when the provider did not say.
	ResetsAt int64 `json:"resetsAt,omitempty"`

	// As the provider reported it, unrounded; it can exceed 100.
	UsedPercent float64 `json:"usedPercent"`
}

// The plan windows of the account this session's assistant runs on: an
// account-level reading shared by every session of that assistant (the Swift
// app's `AssistantQuota.machineLimits`), not this conversation's. An empty
// `windows` is "nobody said", never 0%, and `unknownReason` says which kind of
// nothing it was. It is the same reading GET /v1/orchestrator/assistants
// answers with, age and all, so the two can never show one account two ways.
type SessionLimits struct {
	// How old the provider's record is, in seconds, at the moment this answer was
	// made. Absent when nothing has been read. A percentage is drawn beside its age or
	// it reads as a number from now.
	AgeSeconds *int64 `json:"ageSeconds"`

	// Unix seconds of the provider record the windows came from. Absent when nothing
	// has been read.
	At int64 `json:"at,omitempty"`

	// The same sentence GET /v1/orchestrator/assistants puts in `detail`: what the
	// windows say and how old they are, or which kind of nothing an empty reading was.
	Detail string `json:"detail,omitempty"`

	// How long this reading was good for: five percent of its shortest live window,
	// never under fifteen minutes and never over six hours. Null when there is no
	// reading to age.
	FreshForSeconds *int64 `json:"freshForSeconds"`

	// Unix milliseconds when this daemon took the reading. A client holding readings
	// from several answers keeps the newest by this. Absent for a session with no
	// assistant.
	ReadAtMs int64 `json:"readAtMs,omitempty"`

	// The reading is older than `freshForSeconds`, so these percentages are a lower
	// bound and not a current reading.
	Stale bool `json:"stale,omitempty"`

	// Why there is no reading, when there is none. Absent when windows were read.
	UnknownReason AssistantUnknownReason `json:"unknownReason,omitempty"`
	Windows       []SessionLimitWindow   `json:"windows"`
}

// The question on a waiting session's screen, as rows a finger can hit (the
// Swift app's menuObject). Present only on a waiting session whose screen could
// be read as a menu; a waiting row without it is a question drawn in a shape
// nothing recognised. The row labels and details may be refilled from the
// session's own transcript, but only once the screen proves which question it
// is showing; the numbers, the caret, Submit and the steps are always the
// screen's.
type SessionMenu struct {
	Options []SessionMenuOption `json:"options"`

	// The prose above the rows, or the question as the call asked it. Absent when it
	// could not be read.
	Question string `json:"question,omitempty"`

	// The number of the row the caret is on. Absent when it is on none of them — a
	// multi-select's button can hold it.
	Selected int64 `json:"selected,omitempty"`

	// Where this question sits in a set of them, as the picker's tab bar draws it.
	// Absent for a lone question.
	Steps  []SessionMenuStep  `json:"steps,omitempty"`
	Submit *SessionMenuSubmit `json:"submit,omitempty"`
}

// One row. `n` is the keystroke and not the position: the page sends that
// number to `POST /v1/sessions/{id}/key`, and renumbering would make a button
// answer a different question than its label says.
type SessionMenuOption struct {
	// Whether a keystroke reaches this row (1…9). A row that cannot be answered is
	// drawn and not offered.
	Can bool `json:"can"`

	// Only on a multi-select, where a row ticks rather than answers; present and false
	// is a real answer (the daemon writes it through its own wire type, since a
	// generated optional bool would drop false).
	Checked bool `json:"checked,omitempty"`

	// The prose under the label, joined.
	Detail string `json:"detail,omitempty"`
	Label  string `json:"label"`
	N      int64  `json:"n"`

	// The caret is on this row, so it is what a bare Return would confirm.
	Selected bool `json:"selected"`
}

// One question of a set, as the picker's tab bar names it.
type SessionMenuStep struct {
	// What was chosen, once the picker's review screen names it.
	Answer string `json:"answer,omitempty"`
	Done   bool   `json:"done"`
	Label  string `json:"label"`
}

// The button under a multi-select's rows. It has no number on screen; `POST
// /key` takes the word `submit` for it.
type SessionMenuSubmit struct {
	Label    string `json:"label"`
	Selected bool   `json:"selected"`
}

// One model this session's assistant can be switched to. A session's current
// model is matched against `id` by prefix, so a dated id still finds its row;
// `name` is what a reader is shown for it.
type SessionModel struct {
	Command string `json:"command"`
	ID      string `json:"id"`
	Name    string `json:"name"`
}

// One assistant session. Fields that cannot be supported are absent rather than
// invented; a reader that handles absence handles this too.
type SessionRow struct {
	Activity     *SessionActivity     `json:"activity,omitempty"`
	Assistant    Assistant            `json:"assistant,omitempty"`
	Backend      Backend              `json:"backend"`
	Closeability Closeability         `json:"closeability"`
	Coordination *SessionCoordination `json:"coordination,omitempty"`
	Coordinator  *SessionCoordinator  `json:"coordinator,omitempty"`
	CWD          string               `json:"cwd,omitempty"`
	Disposition  *WorkDisposition     `json:"disposition,omitempty"`
	Evidence     Evidence             `json:"evidence"`
	Icon         *Icon                `json:"icon,omitempty"`
	ID           string               `json:"id"`
	Identity     IdentityBinding      `json:"identity,omitempty"`
	IsClaude     bool                 `json:"isClaude"`

	// What the session is called, by the Swift app's rungs (ITerm.swift
	// preferredDisplayLabel): a name typed in Clawdline (the Swift store's config.json
	// `session_titles`), the title of the task, handoff or Feature Root Clawdline
	// opened the tab for (orchestrator.json), the conversation's own title (`/rename`,
	// else `aiTitle`), Codex's thread name or an automatic title, Claude Code's
	// registry handle — the first that has something. Never a terminal title. Absent
	// when nothing names the session.
	Label string `json:"label,omitempty"`

	// What a working session says it is doing, read from its screen with the
	// assistant's own clock in it. Present while working; on a waiting session with a
	// menu it is instead that menu's revision (the Swift app's menuRevision), which no
	// row draws and which changes whenever the question does. The Swift app sends it
	// under this name and the row's height depends on it.
	Line           string                `json:"line,omitempty"`
	Menu           *SessionMenu          `json:"menu,omitempty"`
	Owed           *WorkOwed             `json:"owed,omitempty"`
	RootAssignment *RootAssignmentRecord `json:"root_assignment,omitempty"`

	// The assistant's own conversation id, when one was recovered from its command
	// line.
	SessionID string `json:"sessionId,omitempty"`

	// The commands this session left running in the background, newest first, at most
	// six. Absent rather than empty when there are none, as the Swift app sends it;
	// always absent for Codex, which keeps no record of them.
	Shells []SessionShell `json:"shells,omitempty"`
	State  SessionState   `json:"state"`
	TTY    string         `json:"tty,omitempty"`

	// Who the declaring session said will move it — a session id, or a person.
	WorkMovedBy string `json:"work_moved_by,omitempty"`

	// The session's own words for its state, present only when its declaration decided
	// `work_state` (then `work_provenance` is `self`).
	WorkNote string `json:"work_note,omitempty"`

	// Whether that mover is a person. Absent unless the declaration decided the state;
	// present and false is a real answer.
	WorkPersonNeeded bool           `json:"work_person_needed,omitempty"`
	WorkProvenance   WorkProvenance `json:"work_provenance,omitempty"`

	// Unix seconds: when that declaration was made.
	WorkSince int64     `json:"work_since,omitempty"`
	WorkState WorkState `json:"work_state"`
}

